// Some portions generated by Claude
export type GeometryNode = {
  entityId: string;
  x: number;
  y: number;
  width: number;
  height: number;
  renderWidth: number;
  renderHeight: number;
  fixed?: number | boolean;
};

export type GeometryEdge = readonly [number, number];

export type LayoutConflictMetrics = {
  nodeOverlaps: number;
  edgeNodeOverlaps: number;
  edgeCrossings: number;
  fanOverlaps: number;
};

type Point = { x: number; y: number };

const TAU = Math.PI * 2;
const EPSILON = 1e-7;

function circularDistance(left: number, right: number) {
  return Math.abs(Math.atan2(Math.sin(left - right), Math.cos(left - right)));
}

function supportRadius(node: GeometryNode, direction: Point, rendered = false) {
  const width = rendered ? node.renderWidth : node.width;
  const height = rendered ? node.renderHeight : node.height;
  return (
    Math.abs(direction.x) * width / 2 +
    Math.abs(direction.y) * height / 2
  );
}

function boxesOverlap(
  left: GeometryNode,
  right: GeometryNode,
  padding = 0,
) {
  return (
    Math.abs(left.x - right.x) <
      (left.renderWidth + right.renderWidth) / 2 + padding * 2 &&
    Math.abs(left.y - right.y) <
      (left.renderHeight + right.renderHeight) / 2 + padding * 2
  );
}

function pointInBox(point: Point, node: GeometryNode, padding = 0) {
  return (
    point.x >= node.x - node.renderWidth / 2 - padding &&
    point.x <= node.x + node.renderWidth / 2 + padding &&
    point.y >= node.y - node.renderHeight / 2 - padding &&
    point.y <= node.y + node.renderHeight / 2 + padding
  );
}

function orientation(start: Point, end: Point, point: Point) {
  return (
    (end.x - start.x) * (point.y - start.y) -
    (end.y - start.y) * (point.x - start.x)
  );
}

function pointOnSegment(start: Point, end: Point, point: Point) {
  return (
    Math.abs(orientation(start, end, point)) < EPSILON &&
    point.x >= Math.min(start.x, end.x) - EPSILON &&
    point.x <= Math.max(start.x, end.x) + EPSILON &&
    point.y >= Math.min(start.y, end.y) - EPSILON &&
    point.y <= Math.max(start.y, end.y) + EPSILON
  );
}

function segmentsIntersect(
  firstStart: Point,
  firstEnd: Point,
  secondStart: Point,
  secondEnd: Point,
  includeTouches = true,
) {
  // Reject disjoint bounding boxes before the four orientation predicates.
  if (Math.max(firstStart.x, firstEnd.x) + EPSILON < Math.min(secondStart.x, secondEnd.x) ||
      Math.max(secondStart.x, secondEnd.x) + EPSILON < Math.min(firstStart.x, firstEnd.x) ||
      Math.max(firstStart.y, firstEnd.y) + EPSILON < Math.min(secondStart.y, secondEnd.y) ||
      Math.max(secondStart.y, secondEnd.y) + EPSILON < Math.min(firstStart.y, firstEnd.y)) return false;
  const firstSideA = orientation(firstStart, firstEnd, secondStart);
  const firstSideB = orientation(firstStart, firstEnd, secondEnd);
  const secondSideA = orientation(secondStart, secondEnd, firstStart);
  const secondSideB = orientation(secondStart, secondEnd, firstEnd);

  if (
    firstSideA * firstSideB < -EPSILON &&
    secondSideA * secondSideB < -EPSILON
  ) {
    return true;
  }
  if (!includeTouches) return false;
  return (
    (Math.abs(firstSideA) < EPSILON &&
      pointOnSegment(firstStart, firstEnd, secondStart)) ||
    (Math.abs(firstSideB) < EPSILON &&
      pointOnSegment(firstStart, firstEnd, secondEnd)) ||
    (Math.abs(secondSideA) < EPSILON &&
      pointOnSegment(secondStart, secondEnd, firstStart)) ||
    (Math.abs(secondSideB) < EPSILON &&
      pointOnSegment(secondStart, secondEnd, firstEnd))
  );
}

function segmentIntersectsNode(
  start: Point,
  end: Point,
  node: GeometryNode,
  padding = 7,
) {
  const halfWidth = node.renderWidth / 2 + padding;
  const halfHeight = node.renderHeight / 2 + padding;
  if (Math.max(start.x, end.x) < node.x - halfWidth ||
      Math.min(start.x, end.x) > node.x + halfWidth ||
      Math.max(start.y, end.y) < node.y - halfHeight ||
      Math.min(start.y, end.y) > node.y + halfHeight) return false;
  if (pointInBox(start, node, padding) || pointInBox(end, node, padding)) {
    return true;
  }
  const left = node.x - node.renderWidth / 2 - padding;
  const right = node.x + node.renderWidth / 2 + padding;
  const top = node.y - node.renderHeight / 2 - padding;
  const bottom = node.y + node.renderHeight / 2 + padding;
  const topLeft = { x: left, y: top };
  const topRight = { x: right, y: top };
  const bottomRight = { x: right, y: bottom };
  const bottomLeft = { x: left, y: bottom };
  return (
    segmentsIntersect(start, end, topLeft, topRight) ||
    segmentsIntersect(start, end, topRight, bottomRight) ||
    segmentsIntersect(start, end, bottomRight, bottomLeft) ||
    segmentsIntersect(start, end, bottomLeft, topLeft)
  );
}

function adjacencyFor(nodeCount: number, edges: GeometryEdge[]) {
  const adjacency = Array.from({ length: nodeCount }, () => new Set<number>());
  edges.forEach(([source, target]) => {
    if (
      source === target ||
      source < 0 ||
      target < 0 ||
      source >= nodeCount ||
      target >= nodeCount
    ) {
      return;
    }
    adjacency[source].add(target);
    adjacency[target].add(source);
  });
  return adjacency;
}

function edgesShareNode(left: GeometryEdge, right: GeometryEdge) {
  return (
    left[0] === right[0] ||
    left[0] === right[1] ||
    left[1] === right[0] ||
    left[1] === right[1]
  );
}

export function measureLayoutConflicts(
  nodes: GeometryNode[],
  edges: GeometryEdge[],
): LayoutConflictMetrics {
  let nodeOverlaps = 0;
  let edgeNodeOverlaps = 0;
  let edgeCrossings = 0;
  let fanOverlaps = 0;

  for (let left = 0; left < nodes.length; left += 1) {
    for (let right = left + 1; right < nodes.length; right += 1) {
      if (boxesOverlap(nodes[left], nodes[right], 3)) nodeOverlaps += 1;
    }
  }

  edges.forEach(([sourceIndex, targetIndex]) => {
    const source = nodes[sourceIndex];
    const target = nodes[targetIndex];
    if (!source || !target) return;
    nodes.forEach((node, nodeIndex) => {
      if (nodeIndex === sourceIndex || nodeIndex === targetIndex) return;
      if (segmentIntersectsNode(source, target, node)) {
        edgeNodeOverlaps += 1;
      }
    });
  });

  for (let left = 0; left < edges.length; left += 1) {
    const leftEdge = edges[left];
    const leftSource = nodes[leftEdge[0]];
    const leftTarget = nodes[leftEdge[1]];
    if (!leftSource || !leftTarget) continue;
    for (let right = left + 1; right < edges.length; right += 1) {
      const rightEdge = edges[right];
      if (edgesShareNode(leftEdge, rightEdge)) continue;
      const rightSource = nodes[rightEdge[0]];
      const rightTarget = nodes[rightEdge[1]];
      if (!rightSource || !rightTarget) continue;
      if (
        segmentsIntersect(
          leftSource,
          leftTarget,
          rightSource,
          rightTarget,
          false,
        )
      ) {
        edgeCrossings += 1;
      }
    }
  }

  const adjacency = adjacencyFor(nodes.length, edges);
  adjacency.forEach((neighbors, hubIndex) => {
    if (neighbors.size < 3) return;
    const hub = nodes[hubIndex];
    const minimumAngle = Math.min(
      7 * Math.PI / 180,
      TAU / neighbors.size * 0.58,
    );
    const rays = [...neighbors]
      .map((neighborIndex) =>
        Math.atan2(
          nodes[neighborIndex].y - hub.y,
          nodes[neighborIndex].x - hub.x,
        ),
      )
      .sort((left, right) => left - right);
    rays.forEach((angle, index) => {
      const next = rays[(index + 1) % rays.length];
      const gap = (next - angle + TAU) % TAU;
      if (gap < minimumAngle) fanOverlaps += 1;
    });
  });

  return {
    nodeOverlaps,
    edgeNodeOverlaps,
    edgeCrossings,
    fanOverlaps,
  };
}

function branchComponents(
  hubIndex: number,
  adjacency: Array<Set<number>>,
) {
  const visited = new Set<number>([hubIndex]);
  const branches: number[][] = [];
  adjacency[hubIndex].forEach((neighborIndex) => {
    if (visited.has(neighborIndex)) return;
    const branch: number[] = [];
    const frontier = [neighborIndex];
    visited.add(neighborIndex);
    while (frontier.length) {
      const nodeIndex = frontier.pop()!;
      branch.push(nodeIndex);
      adjacency[nodeIndex].forEach((nextIndex) => {
        if (nextIndex === hubIndex || visited.has(nextIndex)) return;
        visited.add(nextIndex);
        frontier.push(nextIndex);
      });
    }
    branches.push(branch);
  });
  return branches;
}

function circularMean(values: number[]) {
  if (!values.length) return 0;
  const vector = values.reduce(
    (sum, value) => ({
      x: sum.x + Math.cos(value),
      y: sum.y + Math.sin(value),
    }),
    { x: 0, y: 0 },
  );
  return Math.atan2(vector.y, vector.x);
}

/**
 * WebCola separates rectangles and optimises stress, but it does not reserve
 * an unobstructed edge corridor for each branch of a hub. Removing the hub
 * reveals the branches that a person naturally moves as units. This pass gives
 * each branch a weighted polar sector while preserving its internal geometry.
 */
export function separateHubBranches(
  nodes: GeometryNode[],
  edges: GeometryEdge[],
) {
  if (nodes.length < 10 || edges.length < 9) return false;
  const adjacency = adjacencyFor(nodes.length, edges);
  const hubIndex = adjacency
    .map((neighbors, index) => ({ index, degree: neighbors.size }))
    .sort(
      (left, right) =>
        right.degree - left.degree ||
        nodes[left.index].entityId.localeCompare(nodes[right.index].entityId),
    )[0]?.index;
  if (hubIndex === undefined) return false;
  const hubDegree = adjacency[hubIndex].size;
  const minimumHubDegree = Math.max(8, Math.ceil(Math.sqrt(nodes.length) * 1.25));
  if (hubDegree < minimumHubDegree) return false;
  if (nodes.some((node, index) => index !== hubIndex && node.fixed)) return false;

  const branches = branchComponents(hubIndex, adjacency);
  if (branches.length < 4 || Math.max(...branches.map((branch) => branch.length)) <= 1) {
    return false;
  }
  // A pure star already has the optimal component structure and is handled by
  // the high-degree sunflower pass. Sector packing is for mixed-size branches.
  if (branches.length > 72) return false;

  const hub = nodes[hubIndex];
  const branchData = branches.map((indices) => {
    const indexSet = new Set(indices);
    const attachments = indices.filter((index) => adjacency[index].has(hubIndex));
    const attachmentCenter = attachments.reduce(
      (sum, index) => ({
        x: sum.x + nodes[index].x / attachments.length,
        y: sum.y + nodes[index].y / attachments.length,
      }),
      { x: 0, y: 0 },
    );
    const internalEdgeCount = edges.reduce(
      (count, [source, target]) =>
        count + (indexSet.has(source) && indexSet.has(target) ? 1 : 0),
      0,
    );
    const currentAngle = Math.atan2(
      attachmentCenter.y - hub.y,
      attachmentCenter.x - hub.x,
    );
    const labelDemand = Math.max(
      ...indices.map((index) => nodes[index].renderWidth / 132),
    );
    const weight =
      indices.length === 1
        ? Math.max(0.82, Math.min(1.9, labelDemand))
        : 1.35 +
          Math.sqrt(indices.length) * 1.55 +
          attachments.length * 0.35 +
          internalEdgeCount * 0.12;
    return {
      indices,
      attachments,
      attachmentCenter,
      currentAngle,
      weight,
    };
  });

  branchData.sort(
    (left, right) =>
      left.currentAngle - right.currentAngle ||
      nodes[left.indices[0]].entityId.localeCompare(
        nodes[right.indices[0]].entityId,
      ),
  );
  const totalWeight = branchData.reduce((sum, branch) => sum + branch.weight, 0);
  let accumulatedWeight = 0;
  const relativeCenters = branchData.map((branch) => {
    const center = TAU * (accumulatedWeight + branch.weight / 2) / totalWeight;
    accumulatedWeight += branch.weight;
    return center;
  });
  const phase = circularMean(
    branchData.map(
      (branch, index) => branch.currentAngle - relativeCenters[index],
    ),
  );

  branchData.forEach((branch, branchIndex) => {
    const sectorSpan = TAU * branch.weight / totalWeight;
    const targetAngle = phase + relativeCenters[branchIndex];
    const radial = { x: Math.cos(targetAngle), y: Math.sin(targetAngle) };
    const tangential = { x: -radial.y, y: radial.x };
    const relativeNodes = branch.indices.map((index) => ({
      index,
      x: nodes[index].x - branch.attachmentCenter.x,
      y: nodes[index].y - branch.attachmentCenter.y,
    }));

    let best:
      | {
          rotation: number;
          radius: number;
          score: number;
        }
      | undefined;
    const rotationCandidates =
      branch.indices.length === 1
        ? [0]
        : Array.from({ length: 13 }, (_, index) => (index - 6) * Math.PI / 12);

    rotationCandidates.forEach((rotation) => {
      const cosine = Math.cos(rotation);
      const sine = Math.sin(rotation);
      let minimumParallel = Number.POSITIVE_INFINITY;
      let maximumPerpendicular = 0;
      relativeNodes.forEach(({ index, x, y }) => {
        const rotated = {
          x: x * cosine - y * sine,
          y: x * sine + y * cosine,
        };
        const parallel = rotated.x * radial.x + rotated.y * radial.y;
        const perpendicular =
          rotated.x * tangential.x + rotated.y * tangential.y;
        minimumParallel = Math.min(
          minimumParallel,
          parallel - supportRadius(nodes[index], radial),
        );
        maximumPerpendicular = Math.max(
          maximumPerpendicular,
          Math.abs(perpendicular) + supportRadius(nodes[index], tangential),
        );
      });
      const hubClearance =
        supportRadius(hub, radial) + 132 - minimumParallel;
      const usableHalfAngle = Math.max(0.055, Math.min(0.72, sectorSpan * 0.4));
      const angularClearance =
        maximumPerpendicular / Math.max(0.055, Math.tan(usableHalfAngle));
      const radius = Math.max(
        250,
        hubClearance,
        angularClearance,
        205 + Math.sqrt(branch.indices.length) * 54,
      );
      const rotationCost = Math.abs(rotation) * 8;
      const radialCost = radius * 0.09;
      const score = rotationCost + radialCost;
      if (!best || score < best.score) {
        best = { rotation, radius, score };
      }
    });

    if (!best) return;
    const cosine = Math.cos(best.rotation);
    const sine = Math.sin(best.rotation);
    const targetAttachmentCenter = {
      x: hub.x + radial.x * best.radius,
      y: hub.y + radial.y * best.radius,
    };
    relativeNodes.forEach(({ index, x, y }) => {
      nodes[index].x =
        targetAttachmentCenter.x + x * cosine - y * sine;
      nodes[index].y =
        targetAttachmentCenter.y + x * sine + y * cosine;
    });
  });
  return true;
}

function localConflictScore(
  nodeIndex: number,
  nodes: GeometryNode[],
  edges: GeometryEdge[],
  adjacency: Array<Set<number>>,
  preferredLengths: number[],
  origin: Point,
) {
  const node = nodes[nodeIndex];
  let score = 0;

  nodes.forEach((other, otherIndex) => {
    if (otherIndex === nodeIndex) return;
    if (boxesOverlap(node, other, 5)) score += 120_000;
  });

  edges.forEach(([sourceIndex, targetIndex], edgeIndex) => {
    const source = nodes[sourceIndex];
    const target = nodes[targetIndex];
    if (!source || !target) return;
    const incident = sourceIndex === nodeIndex || targetIndex === nodeIndex;
    if (!incident && segmentIntersectsNode(source, target, node)) {
      score += 48_000;
    }
    if (incident) {
      nodes.forEach((obstacle, obstacleIndex) => {
        if (obstacleIndex === sourceIndex || obstacleIndex === targetIndex) return;
        if (segmentIntersectsNode(source, target, obstacle)) score += 48_000;
      });
      const length = Math.hypot(target.x - source.x, target.y - source.y);
      const preferred = Math.max(1, preferredLengths[edgeIndex]);
      score += Math.abs(length - preferred) * 0.34;
      edges.forEach((otherEdge, otherEdgeIndex) => {
        if (otherEdgeIndex === edgeIndex || edgesShareNode(edges[edgeIndex], otherEdge)) {
          return;
        }
        const otherSource = nodes[otherEdge[0]];
        const otherTarget = nodes[otherEdge[1]];
        if (
          otherSource &&
          otherTarget &&
          segmentsIntersect(source, target, otherSource, otherTarget, false)
        ) {
          score += 7_200;
        }
      });
    }
  });

  adjacency[nodeIndex].forEach((hubIndex) => {
    const hubNeighbors = adjacency[hubIndex];
    if (hubNeighbors.size < 3) return;
    const hub = nodes[hubIndex];
    const angle = Math.atan2(node.y - hub.y, node.x - hub.x);
    const minimumAngle = Math.min(
      8 * Math.PI / 180,
      TAU / hubNeighbors.size * 0.62,
    );
    hubNeighbors.forEach((otherIndex) => {
      if (otherIndex === nodeIndex) return;
      const other = nodes[otherIndex];
      const otherAngle = Math.atan2(other.y - hub.y, other.x - hub.x);
      const gap = circularDistance(angle, otherAngle);
      if (gap < minimumAngle) {
        score += 1_200 * (1 - gap / minimumAngle) ** 2;
      }
    });
  });

  score += Math.hypot(node.x - origin.x, node.y - origin.y) * 0.11;
  return score;
}

function conflictPressure(
  nodes: GeometryNode[],
  edges: GeometryEdge[],
) {
  const pressure = new Array(nodes.length).fill(0);
  for (let left = 0; left < nodes.length; left += 1) {
    for (let right = left + 1; right < nodes.length; right += 1) {
      if (!boxesOverlap(nodes[left], nodes[right], 4)) continue;
      pressure[left] += 100;
      pressure[right] += 100;
    }
  }
  edges.forEach(([sourceIndex, targetIndex]) => {
    const source = nodes[sourceIndex];
    const target = nodes[targetIndex];
    if (!source || !target) return;
    nodes.forEach((node, nodeIndex) => {
      if (nodeIndex === sourceIndex || nodeIndex === targetIndex) return;
      if (!segmentIntersectsNode(source, target, node)) return;
      pressure[nodeIndex] += 80;
      pressure[sourceIndex] += 14;
      pressure[targetIndex] += 14;
    });
  });
  for (let left = 0; left < edges.length; left += 1) {
    for (let right = left + 1; right < edges.length; right += 1) {
      if (edgesShareNode(edges[left], edges[right])) continue;
      const [leftSourceIndex, leftTargetIndex] = edges[left];
      const [rightSourceIndex, rightTargetIndex] = edges[right];
      if (
        segmentsIntersect(
          nodes[leftSourceIndex],
          nodes[leftTargetIndex],
          nodes[rightSourceIndex],
          nodes[rightTargetIndex],
          false,
        )
      ) {
        pressure[leftSourceIndex] += 18;
        pressure[leftTargetIndex] += 18;
        pressure[rightSourceIndex] += 18;
        pressure[rightTargetIndex] += 18;
      }
    }
  }
  return pressure;
}

/**
 * Deterministic coordinate descent over the actual readability objective:
 * node collisions, edges through unrelated nodes, edge crossings, and crowded
 * hub rays. It deliberately moves nodes instead of adding routing detours.
 */
export function refineLayoutGeometry(
  nodes: GeometryNode[],
  edges: GeometryEdge[],
  options: { passes?: number; radiusScale?: number } = {},
) {
  // Medium-size exploration graphs still need corridor cleanup. Reserve the
  // early return for genuinely huge graphs, after the caller's dedicated
  // high-degree sunflower pass has handled the most expensive star layouts.
  if (!nodes.length || nodes.length > 350 || edges.length > 500) {
    return measureLayoutConflicts(nodes, edges);
  }
  const hugeGeometry = nodes.length > 140 || edges.length > 260;
  const largeGeometry = nodes.length > 68 || edges.length > 118;
  const passes = Math.min(
    options.passes ?? 4,
    hugeGeometry ? 2 : largeGeometry ? 3 : 8,
  );
  const radiusScale = options.radiusScale ?? 1;
  const adjacency = adjacencyFor(nodes.length, edges);
  const origins = nodes.map((node) => ({ x: node.x, y: node.y }));
  const preferredLengths = edges.map(([sourceIndex, targetIndex]) =>
    Math.hypot(
      nodes[targetIndex].x - nodes[sourceIndex].x,
      nodes[targetIndex].y - nodes[sourceIndex].y,
    ),
  );
  const directionCount = hugeGeometry ? 8 : largeGeometry ? 10 : 16;
  const directions = Array.from(
    { length: directionCount },
    (_, index) => index * TAU / directionCount,
  );
  const baseRadii = hugeGeometry
    ? [64, 144, 270]
    : largeGeometry
      ? [52, 112, 210, 360]
      : [38, 68, 108, 160, 228, 310, 420, 560];
  const radii = baseRadii.map(
    (radius) => radius * radiusScale,
  );

  for (let pass = 0; pass < passes; pass += 1) {
    const pressure = conflictPressure(nodes, edges);
    const orderedIndices = pressure
      .map((value, index) => ({ index, value }))
      .filter(({ index, value }) => value > 0 && !nodes[index].fixed)
      .sort(
        (left, right) =>
          right.value - left.value ||
          adjacency[left.index].size - adjacency[right.index].size ||
          nodes[left.index].entityId.localeCompare(nodes[right.index].entityId),
      )
      .slice(0, hugeGeometry ? 20 : largeGeometry ? 40 : 72);
    let moved = 0;

    orderedIndices.forEach(({ index: nodeIndex }) => {
      const node = nodes[nodeIndex];
      const start = { x: node.x, y: node.y };
      let best = start;
      let bestScore = localConflictScore(
        nodeIndex,
        nodes,
        edges,
        adjacency,
        preferredLengths,
        origins[nodeIndex],
      );
      radii.forEach((radius) => {
        directions.forEach((angle) => {
          node.x = start.x + Math.cos(angle) * radius;
          node.y = start.y + Math.sin(angle) * radius;
          const score = localConflictScore(
            nodeIndex,
            nodes,
            edges,
            adjacency,
            preferredLengths,
            origins[nodeIndex],
          );
          if (score + 0.5 < bestScore) {
            bestScore = score;
            best = { x: node.x, y: node.y };
          }
        });
      });
      node.x = best.x;
      node.y = best.y;
      if (best.x !== start.x || best.y !== start.y) moved += 1;
    });

    if (!moved) break;
    const metrics = measureLayoutConflicts(nodes, edges);
    if (
      metrics.nodeOverlaps === 0 &&
      metrics.edgeNodeOverlaps === 0 &&
      metrics.edgeCrossings === 0 &&
      metrics.fanOverlaps === 0
    ) {
      break;
    }
  }
  return measureLayoutConflicts(nodes, edges);
}
